(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.5)*8 + Math.cos((x-y)*0.012-t*0.4)*6;
  const w2y = Math.cos((x-y)*0.01-t*0.45)*8 + Math.sin((x+y)*0.011+t*0.38)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*70, 0.085, 1.8, 1.05]
  ];
  let aS=0, iS=0, a2=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    a2+=Math.sin(d*f*1.3-t*sp*0.8+0.7)*w*0.5;
  }
  const n=8, act=aS/n, inh=iS/n, act2=a2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08-ang*2+t*0.9)*Math.cos(dist*0.03+ang*5-t*1.8)*0.25;
  const laplacian=(Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin(sx*0.08+1)*Math.sin(sy*0.1+2))*0.5;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+spiral2+act2*0.3)*2.0);
  const feed=Math.tanh((act*1.2-inh*0.8+laplacian*0.4)*1.8);
  const cell=Math.tanh((feed*0.7+reaction*0.3)*1.6);
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08*reaction;
  const blend=cell*0.6+reaction*0.3+micro, v=blend*0.5+0.5;
  const pal=[
    [5,10,42],[12,35,82],[8,72,108],[15,115,115],
    [45,155,130],[140,175,90],[210,180,60],[220,140,55],
    [200,95,60],[170,55,55],[110,30,55],[55,15,45],[5,10,42]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.08:1.0;
  const glow=Math.max(0,reaction*0.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*255)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*180)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
